```cpp
#include <iostream>
#include <cstring>
#include <unistd.h>
#include <arpa/inet.h>

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket failed");
        exit(EXIT_FAILURE);
    }

    // Setting up the address structure
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8888);

    // Binding the socket to the specified port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listening for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    std::cout << "Server listening on port 8888..." << std::endl;

    // Accepting a connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("Accept failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    std::cout << "Connection accepted" << std::endl;

    // Reading data from the client
    while (true) {
        int valread = read(new_socket, buffer, 1024);
        if (valread <= 0) {
            break; // Connection closed by client or error
        }
        std::cout << "Received: " << buffer << std::endl;
        memset(buffer, 0, 1024); // Clear the buffer for the next read
    }

    // Closing the sockets
    close(new_socket);
    close(server_fd);

    return 0;
}
```

### Explanation:
1. **Socket Creation**: The `socket()` function creates a new socket.
2. **Binding**: The `bind()` function binds the socket to the specified port (8888 in this case).
3. **Listening**: The `listen()` function puts the socket into listening mode.
4. **Accepting Connections**: The `accept()` function accepts an incoming connection.
5. **Reading Data**: The `read()` function reads data from the connected socket.
6. **Closing Sockets**: The `close()` function closes the sockets when done.

