  if (n === 0) return 0;
  if (n === 1) return 1;

  const A = [[1, 1], [1, 0]];
  const result = matrixExponentiation(A, n - 1);

  return result[0][0];
}

function matrixExponentiation(matrix, power) {
  if (power === 0) return [[1, 0], [0, 1]];

  const halfPowerResult = matrixExponentiation(matrix, Math.floor(power / 2));
  const squaredResult = multiplyMatrices(halfPowerResult, halfPowerResult);

  if (power % 2 === 0) {
    return squaredResult;
  } else {
    return multiplyMatrices(squaredResult, matrix);
  }
}

function multiplyMatrices(a, b) {
  const result = [[0, 0], [0, 0]];

  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      for (let k = 0; k < 2; k++) {
        result[i][j] += a[i][k] * b[k][j];
        result[i][j] %= p;
      }
    }
  }

  return result;
}
