```ocaml
open Gl

let () =
  (* Initialize OpenGL context *)
  let display = Display.create ~width:800 ~height:600 "OpenGL Compute Shader Example" in
  let gl_context = Context.create display in
  Context.make_current gl_context;

  (* Create and compile the compute shader *)
  let shader_source = "
    #version 430 core
    layout(local_size_x = 1) in;
    void main() {
      float a = 2.0f;
      float b = 3.0f;
      float c = a * b;
      gl_GlobalInvocationID.x = int(c);
    }
  " in
  let shader = Program.create_shader Shader.COMPUTE shader_source in
  Program.compile shader;

  (* Bind the compute shader and dispatch it *)
  Program.use_program shader;
  Dispatch.compute 1 1 1;

  (* Read back the result from the global memory *)
  let result_buffer = Buffer.create 1 in
  Buffer.bind Buffer.READ_WRITE result_buffer;
  Buffer.read_pixels 0 0 1 1 (Buffer.format Float32) (Buffer.type_ Int32);

  (* Print the result *)
  Printf.printf "Result: %d\n" (Buffer.get_int32 result_buffer 0);

  (* Clean up *)
  Buffer.delete result_buffer;
  Program.delete shader;
  Context.destroy gl_context;
  Display.destroy display
```

