### Vertex Shader

The vertex shader will pass the position of each vertex to the fragment shader.

```glsl
#version 330 core

layout(location = 0) in vec3 aPos;

out vec2 TexCoords;

void main()
{
    gl_Position = vec4(aPos, 1.0);
    TexCoords = aPos.xy;
}
```

### Fragment Shader

The fragment shader will perform the raycasting calculations.

```glsl
#version 330 core

in vec2 TexCoords;

uniform float screenWidth;
uniform float screenHeight;
uniform float playerX;
uniform float playerY;
uniform float playerAngle;
uniform float fov;
uniform float nearPlane;
uniform float farPlane;

out vec4 FragColor;

float castRay(vec2 origin, vec2 direction)
{
    float t = 0.0;
    while (t < farPlane)
    {
        vec2 point = origin + direction * t;
        if (point.x > -1.0 && point.x < 1.0 && point.y > -1.0 && point.y < 1.0)
        {
            // Check if the point is inside any wall
            // For simplicity, we'll assume there's only one wall defined by two points
            vec2 wallStart = vec2(-0.5, -0.5);
            vec2 wallEnd = vec2(0.5, 0.5);

            vec2 edge1 = wallEnd - wallStart;
            vec2 edge2 = vec2(TexCoords.x, TexCoords.y) - wallStart;

            float dotProduct = dot(edge1, edge2);
            if (dotProduct >= 0.0 && dotProduct <= dot(edge1, edge1))
            {
                return t;
            }
        }
        t += 0.01; // Increment step size
    }
    return farPlane;
}

void main()
{
    float aspectRatio = screenWidth / screenHeight;
    float halfFov = fov / 2.0;

    vec2 dir = vec2(
        cos(playerAngle + halfFov - TexCoords.x * halfFov),
        sin(playerAngle + halfFov - TexCoords.x * halfFov)
    );

    float distance = castRay(vec2(playerX, playerY), dir);

    float height = tan(halfFov) * distance;
    float lineHeight = screenHeight / height;

    float yStart = (screenHeight / 2.0) - (lineHeight / 2.0);
    float yEnd = (screenHeight / 2.0) + (lineHeight / 2.0);

    if (yStart < 0.0 || yEnd > screenHeight)
    {
        discard;
    }

    FragColor = vec4(1.0, 1.0, 1.0, 1.0); // White color for walls
}
```

### Explanation

- **Vertex Shader**: Passes the position of each vertex to the fragment shader.
- **Fragment Shader**:
  - `castRay` function performs the raycasting calculation.
  - The `main` function calculates the direction vector based on the player's angle and the current pixel's horizontal coordinate.
  - It then calls `castRay` to determine the distance to the nearest wall.
  - Finally, it calculates the height of the wall on the screen and draws it with a white color.

