});
```

### TCP Client Implementation

```typescript
import { connect } from 'net';

const HOST = '127.0.0.1';
const PORT = 3000;

const client = connect({ host: HOST, port: PORT }, () => {
    console.log('Connected to server');

    const message = Buffer.from('Hello, Server!');
    client.write(message);

    client.on('data', (data) => {
        console.log(`Received data: ${data.toString()}`);
        client.end();
    });
});

client.on('error', (err) => {
    console.error(`Connection error: ${err.message}`);
});

client.on('close', () => {
    console.log('Connection closed');
});
```

### Explanation

- **Server**: The server listens for incoming connections on port `3000`. When a client connects, it reads any data sent by the client and echoes it back.

- **Client**: The client connects to the server at `127.0.0.1` on port `3000`, sends a message, and then waits for a response before closing the connection.

