import numpy as np

# Define the size of the board
ROWS = 6
COLS = 7

# Initialize the board with empty spaces
board = np.zeros((ROWS, COLS))

def print_board(board):
    for row in range(ROWS):
        for col in range(COLS):
            if board[row][col] == 0:
                print(" ", end=" ")
            elif board[row][col] == 1:
                print("X", end=" ")
            else:
                print("O", end=" ")
        print()

def is_valid_move(board, col):
    return board[0][col] == 0

def drop_piece(board, col, player):
    for row in range(ROWS - 1, -1, -1):
        if board[row][col] == 0:
            board[row][col] = player
            break

def check_win(board, player):
    # Check horizontal locations for win
    for row in range(ROWS):
        for col in range(COLS - 3):
            if board[row][col] == player and board[row][col + 1] == player and board[row][col + 2] == player and board[row][col + 3] == player:
                return True

    # Check vertical locations for win
    for row in range(ROWS - 3):
        for col in range(COLS):
            if board[row][col] == player and board[row + 1][col] == player and board[row + 2][col] == player and board[row + 3][col] == player:
                return True

    # Check positively sloped diagonals
    for row in range(ROWS - 3):
        for col in range(COLS - 3):
            if board[row][col] == player and board[row + 1][col + 1] == player and board[row + 2][col + 2] == player and board[row + 3][col + 3] == player:
                return True

    # Check negatively sloped diagonals
    for row in range(3, ROWS):
        for col in range(COLS - 3):
            if board[row][col] == player and board[row - 1][col + 1] == player and board[row - 2][col + 2] == player and board[row - 3][col + 3] == player:
                return True

    return False

def main():
    current_player = 1
    while True:
        print_board(board)
        col = int(input(f"Player {current_player}, enter column (0-{COLS - 1}): "))
        if not is_valid_move(board, col):
            print("Invalid move. Try again.")
            continue
        drop_piece(board, col, current_player)
        if check_win(board, current_player):
            print_board(board)
            print(f"Player {current_player} wins!")
            break
        current_player = 3 - current_player

if __name__ == "__main__":
    main()
```

This code defines a Connect-4 game where two players take turns dropping their pieces into columns on the board. The game continues until one player connects four pieces horizontally, vertically, or diagonally.

Note: This implementation assumes that the first player is represented by "X" and the second player is represented by "O".

